const DB_NAME="kana-study-ai-db",DB_VERSION=1;
const openDB=()=>new Promise<IDBDatabase>((resolve,reject)=>{const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains("attempts"))db.createObjectStore("attempts",{keyPath:"id",autoIncrement:true});if(!db.objectStoreNames.contains("words"))db.createObjectStore("words",{keyPath:"id"});if(!db.objectStoreNames.contains("settings"))db.createObjectStore("settings",{keyPath:"key"});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});
async function storePut(store:string,value:unknown){const db=await openDB();return new Promise<void>((resolve,reject)=>{const req=db.transaction(store,"readwrite").objectStore(store).put(value);req.onsuccess=()=>resolve();req.onerror=()=>reject(req.error);});}
async function storeAll<T>(store:string){const db=await openDB();return new Promise<T[]>((resolve,reject)=>{const req=db.transaction(store,"readonly").objectStore(store).getAll();req.onsuccess=()=>resolve(req.result as T[]);req.onerror=()=>reject(req.error);});}
async function storeClear(store:string){const db=await openDB();return new Promise<void>((resolve,reject)=>{const req=db.transaction(store,"readwrite").objectStore(store).clear();req.onsuccess=()=>resolve();req.onerror=()=>reject(req.error);});}
const shuffle=<T,>(v:T[])=>[...v].sort(()=>Math.random()-.5),sleep=(ms:number)=>new Promise<void>(r=>setTimeout(r,ms)),id=()=>crypto.randomUUID();
const hiraToKata=(s:string)=>[...s].map(c=>{const n=c.charCodeAt(0);return n>=0x3041&&n<=0x3096?String.fromCharCode(n+0x60):c;}).join("");
const cleanBase=(url:string)=>url.replace(/\/+$/,"").replace(/\/v1$/,"");
const stripJson=(s:string)=>s.replace(/^```(?:json)?/i,"").replace(/```$/,"").trim();
function speakOnce(text:string,rate=.82,voice?:SpeechSynthesisVoice){return new Promise<void>(resolve=>{if(!("speechSynthesis" in window))return resolve();speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang="ja-JP";u.rate=rate;u.pitch=1;u.volume=1;if(voice)u.voice=voice;let done=false;const finish=()=>{if(done)return;done=true;clearTimeout(timer);resolve();};const timer=window.setTimeout(finish,5000);u.onend=finish;u.onerror=finish;speechSynthesis.speak(u);});}

